from apps.consolidation.models import ConsolidationAccountMapping,EliminationJournal
from apps.consolidation.services import consolidated_balance_sheet,consolidated_profit_loss,consolidated_trial_balance
def consolidation_context(*,group,period,user):return {"trial_balance":consolidated_trial_balance(group=group,period=period,user=user),"profit_loss":consolidated_profit_loss(group=group,period=period,user=user),"balance_sheet":consolidated_balance_sheet(group=group,period=period,user=user),"mappings":ConsolidationAccountMapping.objects.filter(group=group).count(),"eliminations":list(EliminationJournal.objects.filter(group=group,period=period,user=user).values("id","entry_number","status")),"limitations":["NCI, equity method, proportionate consolidation, full CTA and consolidated cash flow are unsupported."]}
